CREATE TABLE `renstra_sasaran` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `opd_id` int unsigned NOT NULL,
  `renstra_tujuan_id` int unsigned NOT NULL,
  `csf` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `sasaran` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `status` enum('draft','selesai') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'draft',
  `tahun_mulai` int NOT NULL,
  `tahun_akhir` int NOT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `version_id` int unsigned DEFAULT NULL COMMENT 'dokumen_versi terakhir yang mengubah baris ini',
  `berlaku_sampai` int DEFAULT NULL COMMENT 'tahun terakhir dipakai; NULL = masih berlaku',
  `dihentikan_pada` datetime DEFAULT NULL COMMENT 'terisi = dipensiunkan, BUKAN dihapus',
  `alasan_dihentikan` text COLLATE utf8mb4_general_ci,
  PRIMARY KEY (`id`),
  KEY `renstra_sasaran_opd_id_foreign` (`opd_id`),
  KEY `renstra_sasaran_rpjmd_sasaran_id_foreign` (`renstra_tujuan_id`),
  KEY `idx_renstra_sasaran_aktif` (`dihentikan_pada`),
  KEY `idx_renstra_sasaran_versi` (`version_id`),
  CONSTRAINT `fk_renstra_sasaran_opd` FOREIGN KEY (`opd_id`) REFERENCES `opd` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_renstra_sasaran_renstra_tujuan` FOREIGN KEY (`renstra_tujuan_id`) REFERENCES `renstra_tujuan` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=214 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
