--
-- Table structure for table `renstra_indikator_sasaran`
--

DROP TABLE IF EXISTS `renstra_indikator_sasaran`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `renstra_indikator_sasaran` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `renstra_sasaran_id` int unsigned NOT NULL,
  `indikator_sasaran` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `satuan` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `baseline` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `jenis_indikator` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `version_id` int unsigned DEFAULT NULL COMMENT 'dokumen_versi terakhir yang mengubah baris ini',
  `berlaku_sampai` int DEFAULT NULL COMMENT 'tahun terakhir dipakai; NULL = masih berlaku',
  `dihentikan_pada` datetime DEFAULT NULL COMMENT 'terisi = dipensiunkan, BUKAN dihapus',
  `alasan_dihentikan` text COLLATE utf8mb4_general_ci,
  `indikator_sebelumnya_id` int unsigned DEFAULT NULL COMMENT 'indikator yang digantikan baris ini (lineage)',
  `jenis_perubahan` varchar(20) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'tetap' COMMENT 'tetap|revisi|pengganti|baru|dihentikan',
  `perubahan_substansial` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1 = tren antar tahun tidak boleh disambung',
  PRIMARY KEY (`id`),
  KEY `renstra_indikator_sasaran_renstra_sasaran_id_foreign` (`renstra_sasaran_id`),
  KEY `idx_renstra_indikator_sasaran_aktif` (`dihentikan_pada`),
  KEY `idx_renstra_indikator_sasaran_versi` (`version_id`),
  KEY `idx_renstra_indsas_lineage` (`indikator_sebelumnya_id`),
  CONSTRAINT `fk_renstra_indsas_sebelumnya` FOREIGN KEY (`indikator_sebelumnya_id`) REFERENCES `renstra_indikator_sasaran` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_renstra_indsasaran_sasaran` FOREIGN KEY (`renstra_sasaran_id`) REFERENCES `renstra_sasaran` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=521 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

