--
-- Table structure for table `dokumen_versi`
--

DROP TABLE IF EXISTS `dokumen_versi`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `dokumen_versi` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `modul` varchar(10) COLLATE utf8mb4_general_ci NOT NULL COMMENT 'rpjmd | renstra | iku | lakip',
  `scope` varchar(12) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'kabupaten' COMMENT 'kabupaten | opd',
  `opd_id` int unsigned DEFAULT NULL COMMENT 'NULL bila scope=kabupaten',
  `periode_mulai` int NOT NULL,
  `periode_akhir` int NOT NULL COMMENT 'untuk modul=lakip: sama dengan periode_mulai (satu tahun)',
  `version_no` int NOT NULL DEFAULT '1' COMMENT 'BUKAN penentu waktu berlaku (┬º2.6)',
  `label` varchar(255) COLLATE utf8mb4_general_ci NOT NULL COMMENT 'mis. "V3 ÔÇö Penyesuaian RPJMD Tahun 2026"',
  `effective_from` date NOT NULL COMMENT 'inklusif ÔÇö SATU-SATUNYA penentu timeline',
  `effective_to` date DEFAULT NULL COMMENT 'EKSKLUSIF; dihitung sistem, bukan diedit user',
  `status` varchar(20) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'draft' COMMENT 'draft | pending_approval | published | cancelled',
  `copied_from_version_id` int unsigned DEFAULT NULL COMMENT 'deep copy dari versi ini (┬º10)',
  `mulai_dari_kosong` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1 = input dari kosong',
  `source_type` varchar(10) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'rpjmd | renstra | iku ÔÇö sync IKU (┬º15) / source LAKIP (┬º25)',
  `source_version_id` int unsigned DEFAULT NULL,
  `source_captured_at` datetime DEFAULT NULL COMMENT 'terisi = tautan BEKU; sync ulang wajib versi baru (┬º15)',
  `source_override_reason` text COLLATE utf8mb4_general_ci COMMENT 'WAJIB bila source bukan rekomendasi resolver (┬º27)',
  `source_override_dasar` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `alasan_perubahan` text COLLATE utf8mb4_general_ci,
  `dasar_perubahan` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `nomor_dasar` varchar(150) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `tanggal_dasar` date DEFAULT NULL,
  `catatan` text COLLATE utf8mb4_general_ci,
  `ref_id` int unsigned DEFAULT NULL COMMENT 'iku_revisi.id / lakip_snapshot.id (┬º42)',
  `created_by` int unsigned DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `submitted_by` int unsigned DEFAULT NULL,
  `submitted_at` datetime DEFAULT NULL,
  `approved_by` int unsigned DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `cancelled_by` int unsigned DEFAULT NULL,
  `cancelled_at` datetime DEFAULT NULL,
  `applied_at` datetime DEFAULT NULL COMMENT 'kapan arsip diterapkan ke tabel live',
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `opd_key` int unsigned GENERATED ALWAYS AS (coalesce(`opd_id`,0)) STORED,
  `scope_key` varchar(12) COLLATE utf8mb4_general_ci GENERATED ALWAYS AS (coalesce(`scope`,_utf8mb4'kabupaten')) STORED,
  `published_key` tinyint GENERATED ALWAYS AS ((case when (`status` = _utf8mb4'published') then 1 else NULL end)) STORED,
  `terbuka_key` tinyint GENERATED ALWAYS AS ((case when ((`status` = _utf8mb4'published') and (`effective_to` is null)) then 1 else NULL end)) STORED,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_dokver_nomor` (`modul`,`scope_key`,`opd_key`,`periode_mulai`,`periode_akhir`,`version_no`),
  UNIQUE KEY `uq_dokver_mulai` (`modul`,`scope_key`,`opd_key`,`periode_mulai`,`periode_akhir`,`effective_from`,`published_key`),
  UNIQUE KEY `uq_dokver_terbuka` (`modul`,`scope_key`,`opd_key`,`periode_mulai`,`periode_akhir`,`terbuka_key`),
  KEY `idx_dokver_lingkup` (`modul`,`scope_key`,`opd_key`,`periode_mulai`,`periode_akhir`,`status`),
  KEY `idx_dokver_efektif` (`modul`,`status`,`effective_from`,`effective_to`),
  KEY `idx_dokver_opd` (`opd_id`),
  KEY `idx_dokver_ref` (`modul`,`ref_id`),
  KEY `idx_dokver_copy` (`copied_from_version_id`),
  KEY `idx_dokver_source` (`source_type`,`source_version_id`),
  KEY `fk_dokver_source` (`source_version_id`),
  CONSTRAINT `fk_dokver_copy` FOREIGN KEY (`copied_from_version_id`) REFERENCES `dokumen_versi` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_dokver_source` FOREIGN KEY (`source_version_id`) REFERENCES `dokumen_versi` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=67 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='Registri versi lintas dokumen (┬º3/┬º7/┬º8). version_no != waktu berlaku.';
